  'landing.stD1': 'Education mode — the exercise and the round trip around it run; the course above them is in development',
  'landing.stD2': 'PRO mode — advanced analysis and concrete design today, detailing and export expanding',
  'landing.stD3': 'Stabileo AI — the agent layer, in development on the same solver',
  'landing.proNow6': 'One-way and two-way slabs, walls and pad footings are designed too, from a real command in the workflow. These results are labelled provisional while they are tested against real projects.',
  'landing.proNow7': 'Reinforcement drawings for five element families: beam and column elevations with their sections, footing plans with two sections, slab panel plans, and wall elevations and sections. They export as DXF and SVG.',
  'landing.proNow8': 'A bar bending schedule with marks, diameters, shapes, quantities, cutting lengths measured along the physical bar including its hook arcs, mass, commercial stock bars and offcuts, plus a note wherever a bar exceeds stock length and needs a splice. It exports to XLSX.',
  'landing.proNext6': 'Torsion, beam-column joints, diaphragms and non-rectangular sections.',
  'landing.proSourceNote': 'Statuses here follow the application’s own maturity model: a calculation counts as validated once an independent external benchmark is on file, and until then it is labelled provisional, in the product and on this page.',
  'landing.stPa5': 'Slabs, walls and pad footings are designed and reachable in the workflow, and are being tested against real projects',
  'landing.modesLead': 'All four grow on the same solver. Basic is the structural-analysis mode you can use today; Education, PRO and Stabileo AI extend it with learning, advanced engineering and agent workflows.',
  'landing.proNext7': 'International code support, after CIRSOC.',
  'landing.badgeTesting': 'PARTIAL · IN TESTING',
  'landing.codesLead': 'Member checking already spans the main international codes. Code-based design, meaning proposing a design and generating reinforcement, is being built out one framework at a time.',
  'landing.codesIntlLead': 'The solver rates a member you designed against each of these today.',
