  // Advanced help texts
  'advHelp.pdelta.label': 'P-\u0394 (2nd Order)',
  'advHelp.pdelta.text': 'Geometric nonlinear analysis. Considers how axial forces modify the lateral stiffness of the structure (P-\u0394 effect). Iterates until convergence and reports the amplification factor B\u2082. If B\u2082 > 1.4, the structure is sensitive to second-order effects. Requires solving first.',
  'advHelp.buckling.label': 'Pcr \u2014 Critical Load (Euler)',
  'advHelp.buckling.text': 'Computes the elastic buckling load via eigenvalues of the geometric stiffness matrix. The factor \u03BB_cr indicates how much the current loads would need to be multiplied for the structure to buckle. If \u03BB_cr < 1, the structure has already exceeded its critical load. Shows the effective length (Keff) of each compressed member.',
  'advHelp.modal.label': 'Dynamic Analysis (Modal)',
  'advHelp.modal.text': 'Computes vibration modes and natural frequencies using the consistent mass matrix. Reports: frequency (Hz), period (s), effective modal mass (%) in X and Y, and Rayleigh damping coefficients. Prerequisite for spectral analysis. Requires material density (\u03C1).',
  'advHelp.spectral.label': 'Spectral Analysis (CIRSOC 103)',
  'advHelp.spectral.text': 'Modal spectral combination with CIRSOC 103 seismic design spectrum (Argentina). Computes base shear, displacements, and peak forces by combining modes using CQC or SRSS. Requires running dynamic analysis first. Uses Zone 4, Soil type II by default.',
  'advHelp.plastic.label': 'Plastic Collapse',
  'advHelp.plastic.text': 'Incremental analysis that forms plastic hinges at points where the moment reaches Mp (plastic moment = Wpl \u00D7 fy). At each step, the structure is recalculated with the new hinge. The factor \u03BB indicates how much to multiply the loads to reach the collapse mechanism. Requires material fy.',
  'advHelp.dsm.label': 'Step by Step \u2014 Direct Stiffness Method',
  'advHelp.dsm.text': 'Shows each step of the Direct Stiffness Method in detail: DOF numbering, local stiffness matrices [k], transformations [T], global assembly [K], load vector {F}, boundary conditions, system solution {u} = [K]\u207B\u00B9{F}, and extraction of reactions and internal forces. Ideal for studying and learning the method.',
  'advHelp.envelope.label': 'Force Envelope',
  'advHelp.envelope.text': 'Force envelope from load combinations. Solves each load case separately and combines them with the factors defined in the combinations table (e.g., 1.2D + 1.6L). Shows the maximum and minimum (+/\u2212) envelope of moment, shear, and axial force. Allows comparing individual combinations from the "Primary" dropdown in Settings \u2192 Results. Requires combinations defined in the "Combinations" tab.',
  'advHelp.trainLoad.label': 'Moving Load',
  'advHelp.trainLoad.text': 'A load train (e.g., HL-93 truck, tandem) traverses the structure at multiple positions. At each position, the full structure is solved and forces are recorded. Train loads are ADDED to existing model loads \u2014 to see only the train effect, remove other loads. After solving, use the \u25C0\u25B6 arrows to step through positions and "View envelope" to see the maximum and minimum forces across all positions. Classic tool for bridge and vehicular load design.',
  'advHelp.influenceLine.label': 'Influence Line',
  'advHelp.influenceLine.text': 'Shows how a fixed quantity (reaction, moment, or shear at a specific section) varies when a unit load P=1 traverses the structure. Click a node to see the IL of its reactions (Ry, Rx, Mz) or a member for M or V at that section. Classic tool for bridge and moving load design. Shortcut: key I.',
  'advHelp.despiece.label': 'Free-body view (despiece)',
  'advHelp.despiece.text': 'Educational view that pulls each member off its joints and draws the internal end forces it transmits — axial N, shear V and moment M — plus support reactions. Members sharing a joint show equal/opposite action–reaction pairs across the gap. Requires a solved model; uses the current results. Visualization only — it does not change the model or run a new analysis.',
  'advHelp.kinematic.label': 'Kinematic Analysis',
  'advHelp.kinematic.text': 'Step-by-step analysis of the kinematic stability of the structure. Shows the degree of static indeterminacy (detailed formula with each support and hinge), numerically verifies via Kff rank if hidden mechanisms exist, and suggests corrections if the structure is unstable. Works without solving \u2014 updates in real time as the model is modified.',
  'advHelp.stress.label': 'Stress \u2014 Section Analysis',
  'advHelp.stress.text': 'Complete stress analysis of cross-sections. Click a member to see: normal stress \u03C3 (Navier: \u03C3 = N/A + M\u00B7y/I), shear stress \u03C4 (Jourawski: \u03C4 = V\u00B7Q/(I\u00B7b)), Von Mises equivalent stress (\u03C3_vm = \u221A(\u03C3\u00B2 + 3\u03C4\u00B2)), Mohr\'s circle with principal stresses, shear flow diagram for thin-walled profiles, and utilization ratio vs fy. Includes a slider to traverse section fibers (0=bottom, 1=top) and navigation to critical sections (max moment, supports, load points). Supports rectangular, I, U, L, box (RHS), and tubular (CHS) sections.',
  'advHelp.whatif.label': 'Explore (What if\u2026?)',
  'advHelp.whatif.text': 'Interactive parametric sensitivity analysis panel. Adjust load magnitudes, material elastic modulus E, and section properties (area A and inertia Iz) in real time using sliders. The structure recalculates instantly with each change (~60ms) showing how diagrams, deformed shapes, and reactions vary. Ideal for understanding structural behavior, optimizing sections, and answering questions like "what if I double the load?" or "what if I use a stiffer profile?". Changes are temporary \u2014 the original model is restored when the panel is closed.',

