  // ─── Section Stress Panel ───
  'stress.panelTitle': 'Section Analysis',
  'stress.close': 'Close (Esc)',
  'stress.moveAlongElem': 'Move along element (x/L)',
  'stress.forces3dHelp': '3D internal forces at this section.\nN = normal (+ tension, - compression)\nVy = shear in XY plane (produces Mz)\nVz = shear in XZ plane (produces My)',
  'stress.moments3dHelp': 'Mx = torsional moment\nMy = moment about local y (bends over the depth, uses Iy)\nMz = moment about local z (bends over the width, uses Iz)\nDefault unrolled tall section: My is the strong/vertical axis, Mz the weak/lateral — a section roll rotates these with the section.\nConvention: + = sagging (tension at bottom fiber)',
  'stress.rotDecompHelp': 'Section rotation decomposition ({angle}\u00B0).\nVy, Vz = shear components in rotated local axes',
  'stress.rotMomentHelp': 'Moment M decomposition by section rotation.\nMy = M\u00B7cos(\u03B1) (depth/strong-axis bending at \u03B1=0)\nMz = M\u00B7sin(\u03B1) (width/weak-axis bending at \u03B1=0)\n\u03B1 = {angle}\u00B0',
  'stress.forces2dHelp': 'Internal forces at this element section.\nN = normal (+ tension, - compression)\nV = transverse shear\nM = bending moment (+ sagging, tension at bottom)',
  'stress.criticalSections': 'Critical sections',
  'stress.criticalSectionsHelp': 'Positions along the element where stresses should be checked.\n\nIncludes points of maximum moment (V=0), supports, point loads and intermediate points.\nClick each chip to navigate to that section.',
  'stress.noGeomMsg1a': 'The exact outline of ',
  'stress.noGeomMsg1b': ' is not available yet, so the stress distribution, Mohr circle and failure criteria cannot be computed for it.',
  'stress.cpInKern': 'in NC: σ same sign',
  'stress.naOutside': 'EN {arrow} outside',
  'stress.rotSuffix': '(rot {angle}°)',
  'stress.noGeomMsg2': 'This is a missing-data limitation, not a property of the section: the profile is perfectly well defined and the global analysis uses its published values normally.',
  'stress.noGeomMsg3': 'Every catalogue family except MC supports detailed analysis. Assign one of those, or build a section with explicit dimensions.',
  'stress.amorphMsg1': 'The selected section is <strong>amorphous</strong> (no defined geometric shape).',
  'stress.amorphMsg2': 'Amorphous sections do not support stress distribution analysis, Mohr\u2019s circle, or failure criteria.',
  'stress.amorphMsg3': 'To enable section analysis, assign a standard profile or build a section with geometric shape.',

  // ─── Stress State Details ───
  'stress.stressState': 'Stress state',
  'stress.sigmaBiaxHelp': 'Biaxial normal stress (Navier):\n\u03C3 = N/A \u2212 My\u00B7y/Iy + Mz\u00B7z/Iz\n\nPositive = tension (red)\nNegative = compression (blue)\n\nDepends on selected fiber (y, z).',
  'stress.tauTotalHelp': 'Total combined shear stress:\n\u03C4 = \u221A(\u03C4Vy\u00B2 + \u03C4Vz\u00B2 + \u03C4T\u00B2)\n\nIncludes shear from Vy (XY plane), Vz (XZ plane) and torsion.',
  'stress.vonMisesHelp': 'Von Mises criterion (distortion energy):\n\u03C3vm = \u221A(\u03C3\u00B2 + 3\u03C4\u00B2)\n\nPreferred for steel and ductile metals.\nPercentage shows fy capacity usage.',
  'stress.trescaHelp': 'Tresca criterion (max. shear stress):\n\u03C4max = \u221A((\u03C3/2)\u00B2 + \u03C4\u00B2)\n\n~15% conservative vs Von Mises.\nEquivalent: 2\u03C4max \u2264 fy',
  'stress.rankineHelp': 'Rankine criterion (max. normal stress):\nmax(|\u03C3\u2081|, |\u03C3\u2083|) \u2264 fy\n\nAppropriate for brittle materials (concrete, rock).\nFor steel, prefer Von Mises.',
  'stress.neutralAxis': 'Neutral axis:',
  'stress.neutralAxis3dHelp': 'Combined neutral axis where \u03C3=0.\nWith biaxial bending (Mz and My), the neutral axis can be oblique.\n\u03B8 is the angle from the Z axis (horizontal).',
  'stress.sigma2dHelp': 'Normal stress (Navier formula):\n\u03C3 = N/A + M\u00B7y/I\n\nPositive = tension (red)\nNegative = compression (blue)\n\nDepends on selected fiber (y).',
  'stress.tauMassiveHelp': 'Shear stress (Jourawski):\n\u03C4 = V\u00B7Q(y) / (I\u00B7b)\n\nQ(y) = first moment of area above y.\nMaximum at neutral axis, zero at free edges.\nParabolic distribution in rectangular sections.\n\nAssumption: \u03C4 uniform across width b.\nFor wide sections (b \u2248 h) this is approximate;\nactual value varies in z (maximum at center).',
  'stress.tauThinHelp': 'Shear stress (Jourawski):\n\u03C4 = V\u00B7Q(y) / (I\u00B7b)\n\nQ(y) = first moment of area above y.\nMaximum at neutral axis, zero at free edges.\n\nFor thin-walled profiles the assumption of\n\u03C4 uniform across thickness is very accurate.',
  'stress.neutralAxisLabel': '(neutral axis)',
  'stress.note2dTauOnly': '2D analysis: only \u03C4xy from shear V',
  'stress.note2dNoTorsion': 'No torsion (T=0) or out-of-plane shear (Vz=0)',
  'stress.neutralAxis2dHelp': 'Neutral axis (\u03C3 = 0):\ny_NA = -N\u00B7Iz / (A\u00B7M)\n\nPosition where normal stress vanishes.\nPositive = above centroid.\nIf N=0, NA passes through centroid (y=0).',

  // ─── Central Core ───
  'stress.centralCore': 'Central core',
  'stress.centralCoreHelp': 'The CC is a geometric property of the section.\nDefines where N can act without sign change in \u03C3.\nEnable the CC button on the cross section to visualize it.',
  'stress.ccDesc1': 'The <strong>central core</strong> is a geometric property of the cross section, independent of applied loads.',
  'stress.ccDesc2': 'Defines the region around the centroid where a normal force N can act without producing a sign change in normal stresses \u03C3. If the pressure center falls inside the CC, the entire section is in pure tension or compression.',
  'stress.ccLimitZ': "Along the horizontal axis",
  'stress.ccLimitY': "Along the vertical axis",
  'stress.ccEquations': 'Equations',
  'stress.ccEqDesc': 'For each extreme fiber at distance <em>d</em> from the centroid, the CC vertex is at:',
  'stress.ccEqWhere': 'where W = section modulus, A = area, I = moment of inertia, d = distance to extreme fiber.',
  'stress.sectionLabel': 'Section:',
  'stress.ccShapeLabel': 'CC shape:',
