  'stress.ccRectNote': 'Diamond with semi-axes e<sub>y</sub> = h/6 and e<sub>z</sub> = b/6',
  'stress.ccIHNote': 'Hexagon: vertices at (0, \u00B1I<sub>z</sub>/(A\u00B7h/2)) and (\u00B1I<sub>y</sub>/(A\u00B7b/2), \u00B1I<sub>z</sub>/(A\u00B7y<sub>web</sub>))',
