  'kin.classHypostatic': 'Hypostatic — missing {n} constraint{s}. The structure is a mechanism.',
  'kin.classHiddenMechZero': 'The formula gives g = 0 (necessary condition for isostatic), but NOT sufficient. The numerical verification (Step 3) detected {modes} mechanism mode{s}. This occurs when the constraints are poorly distributed: one zone has excess constraints and another zone lacks them.',
  'kin.classHiddenMechPos': 'The formula gives g = {degree} > 0 (appears hyperstatic), but the numerical verification (Step 3) detected {modes} mechanism mode{s}. This occurs when the constraints are poorly distributed: one zone is hyperstatic (has excess constraints) while another is hypostatic (lacks constraints). The excess in one zone does not compensate the deficit in another.',
  'kin.classIsostatic': 'Isostatic — the number of constraints is exactly what is needed. No redundancy.',
  'kin.classHyperstatic': 'Hyperstatic of degree {degree} — there are {degree} equilibrium equation{s} more than necessary to ensure stability.',
  'kin.plural_s': 's',
  'kin.plural_n': '',

