  'footing.migration.matPolicyUnknown': 'The stored bottom-mat spacing policy “{value}” is not one this version knows. Spacing was derived from the code, which is the only policy implemented.',
  'footing.migration.layerOrderToAuto': 'The project did not state which bottom mat goes in the lower layer, so the layer order was read as AUTOMATIC. This CHANGES the design relative to the previous version: both directions used to be designed at the shallower effective depth (a conservative envelope) and each is now designed at its real depth. The order can be fixed by hand in Foundations.',
  'footing.migration.layerOrderUnknown': 'The stored bottom-mat layer order “{value}” is not one this version knows. It was read as AUTOMATIC: an order that cannot be placed is not a placement instruction.',

